      "镜像在仓库中通常通过 name:tag 引用，例如 nginx:1.27；更精确的内容标识是 digest，例如 sha256:...。生产发布建议记录 digest，便于复现同一份镜像内容。",
      "OCI Image Specification 定义了镜像的 manifest、config 和 layers 等结构。manifest 描述层和配置，config 包含环境变量、入口命令、工作目录、架构和历史信息。",
      "docker image ls 适合查看本地镜像列表，docker pull 负责从仓库拉取镜像，docker image inspect 可以查看镜像 ID、digest、架构、层、配置、标签和大小等细节。",
      "多架构镜像会把同一个标签映射到不同平台的镜像内容，例如 linux/amd64 和 linux/arm64。构建和部署跨平台应用时要明确目标 platform。",
      "镜像安全关注基础镜像来源、漏洞扫描、密钥泄漏、过期依赖和过大攻击面。Docker Scout 等工具可以帮助检查镜像漏洞、基础镜像更新建议和供应链风险。",
      "常见问题包括 latest 标签漂移、镜像体积膨胀、把密钥写入镜像层、平台架构不匹配、镜像仓库拉取限速、缓存命中异常、标签覆盖导致回滚困难。",
