    explanation: [
      "镜像标签是镜像名称后面的可读标识，例如 nginx:1.27、app:2026-05-31、registry.example.com/team/app:prod。它让人和自动化系统用稳定命名引用镜像。",
      "一个镜像可以拥有多个 tag，同一个 tag 也可以在后续 push 中指向新的镜像内容。tag 是可变引用，digest 是内容地址，生产追溯通常需要同时记录 tag 和 digest。",
      "docker image tag 只是在本地为已有镜像增加一个引用，随后 docker image push 才会把这个引用推送到仓库。仓库中的同名 tag 被重新推送后，拉取者会拿到新的内容。",
      "常见标签策略包括语义化版本 1.4.2、Git SHA、构建号、日期、环境名和渠道名。语义化版本适合发布沟通，Git SHA 适合精确追溯，环境标签适合流水线流转。",
      "latest 只是普通标签，通常表示仓库维护者当前选定的默认版本。它会随推送变化，适合本地体验和示例，生产部署应使用明确版本或 digest。",
      "镜像完整引用由 registry、namespace/repository、tag 组成。省略 registry 时通常使用默认 Docker Hub，省略 tag 时常按 latest 处理，这些默认行为容易造成拉取来源和版本误判。",
      "多架构镜像场景中，同一个 tag 可能指向 manifest list，再按平台选择具体镜像。排查跨平台问题时要结合 docker image inspect 或 buildx imagetools 查看平台映射。",
      "常见问题包括覆盖 tag 导致回滚困难、CI 并发推送同一 tag、latest 漂移、本地旧 tag 与远端内容不一致、私有仓库命名错误、镜像清理误删仍在使用的 tag。",
      "参考来源：本讲解参考 docker image tag、docker image push、docker image ls、docker image inspect、docker image pull、Docker Hub Repositories and images、OCI Image Specification 和《Docker 从入门到实践》的架构说明。",
    ],
