    id: "image-digest",
    zh: "镜像摘要",
    en: "Image Digest",
    area: "image",
    difficulty: "medium",
    concept: "镜像摘要是镜像内容的加密哈希标识，用于精确锁定同一份镜像内容。",
    explanation: [
      "镜像摘要是内容寻址标识，常见形式是 sha256:...。它由镜像 manifest 或 manifest list 的内容计算得出，内容变化会产生新的 digest。",
      "tag 是可读且可变的引用，digest 是内容绑定的引用。使用 repo/app@sha256:... 拉取镜像时，客户端会请求这份具体内容，适合可复现部署和供应链追溯。",
      "OCI Image Specification 中 descriptor 使用 digest、mediaType、size 描述对象。镜像 manifest、config、layer 都可以通过 digest 被引用和校验。",
      "docker images --digests 可以查看本地镜像关联的仓库摘要，docker image inspect 可以查看 RepoDigests、Id、RootFS layers 等字段。发布记录中保存 RepoDigest 能把版本还原到具体内容。",
      "多架构镜像中，一个 tag 可能对应 manifest list digest，manifest list 再指向不同平台的镜像 manifest digest。排查平台差异时要区分列表摘要和具体平台摘要。",
      "digest 能保证内容定位和完整性校验，签名系统负责身份与信任判断。Docker Content Trust、Notary、cosign 等机制会在 digest 之上提供发布者可信度和防篡改链路。",
      "常见问题包括把 digest 当成人类版本号使用、只记录 tag 导致无法复现、复制了错误平台的 digest、仓库垃圾回收影响旧内容可用性、镜像重建后 digest 变化但 tag 名相同。",
      "实践上，tag 适合表达业务版本，digest 适合锁定发布内容。部署清单、审计记录、回滚记录和漏洞扫描结果都应保存 digest。",
      "参考来源：本讲解参考 Docker Image digests、docker image pull、docker image ls、docker image inspect、OCI Image Specification、OCI Descriptor、Docker Content Trust 和 Docker Hub Repositories and images。",
    ],
