      "ENV 常用于声明应用默认端口、运行模式、语言运行时配置和工具路径。例如 ENV NODE_ENV=production、ENV PATH=/app/bin:$PATH，后续 RUN、CMD、ENTRYPOINT 都可引用这些值。",
      "运行容器时，docker run -e KEY=value、--env-file、Compose environment 和 env_file 可以注入或覆盖环境变量。镜像 ENV 提供默认值，部署环境负责给出环境差异。",
      "ENV 与 ARG 的作用域不同。ARG 面向构建参数，主要在 build 阶段使用；ENV 会进入镜像配置并影响运行容器。需要把构建参数转成运行默认值时，可以用 ARG 配合 ENV 显式传递。",
      "ENV 指令本身主要改变镜像元数据，但它会影响后续指令的变量替换和缓存命中。修改 ENV 后，依赖它的 RUN、CMD、ENTRYPOINT 或 COPY 参数通常需要重新构建相关层。",
      "敏感信息适合走运行时密钥、secret 文件或平台级配置。ENV 值容易出现在 docker inspect、镜像历史、进程环境和日志中，账号、令牌、私钥等信息进入 ENV 后泄露面会扩大。",
