      "ARG 适合表达构建输入，例如 VERSION、TARGETPLATFORM、HTTP_PROXY、ENABLE_FEATURE。需要把构建输入变成运行默认值时，可以显式写成 ARG VERSION 后接 ENV APP_VERSION=$VERSION。",
      "ARG 会参与构建缓存。ARG 值变化时，依赖该参数的指令以及后续相关层会重新执行；用于 FROM 的 ARG 变化时，基础镜像链路也会改变。",
      "BuildKit 和 buildx 提供一组预定义构建参数，例如 BUILDPLATFORM、TARGETPLATFORM、TARGETOS、TARGETARCH。跨平台构建时，这些参数能帮助 Dockerfile 选择正确依赖和产物。",
      "ARG 值可能出现在构建记录、镜像历史或 provenance 信息中。令牌、密码、私钥这类敏感信息应通过 build secrets 传入，避免用 ARG 或 ENV 承载。",
      "常见边界包括 FROM 前 ARG 未在阶段内重新声明、默认值为空导致镜像名无效、--build-arg 拼写错误、布尔开关在 shell 中被字符串化、ARG 修改触发缓存失效、把代理或令牌残留到镜像层。",
