    concept: "构建上下文是 Docker 构建器可读取的文件集合，决定 COPY/ADD 的可见范围、传输成本、缓存校验和敏感文件暴露面。",
    explanation: [
      "构建上下文是执行 docker build 时传给构建器的一组输入文件。命令末尾的路径、Git URL、远程 tar 包或标准输入会决定构建器能看到哪些文件。",
      "本地构建最常见写法是 docker build .，其中 . 表示把当前目录作为上下文。Dockerfile 可以通过 -f 指向其他位置，COPY 和 ADD 默认读取的文件范围仍由构建上下文决定。",
      ".dockerignore 会在上下文发送给构建器前排除文件。排除 node_modules、dist、日志、缓存、.git、密钥和本地配置，可以减少传输体积、降低泄露风险，并让缓存输入更稳定。",
      "构建上下文会影响缓存。COPY/ADD 参与缓存校验的文件内容和元数据变化时，该指令及后续层会重新构建；把依赖清单和源码拆开复制，通常能减少无关代码改动造成的缓存失效。",
      "BuildKit 支持远程 Git 上下文、远程 tar 上下文、标准输入 Dockerfile、空上下文和 named contexts。命名上下文能把文档、产物或外部源码拆成独立输入，再通过 COPY --from=<name> 或 RUN --mount 使用。",
      "上下文大小直接影响构建速度和 CI 稳定性。远程构建器、Docker Desktop、Buildx 或云构建场景中，上下文需要上传到构建端，过大的目录会拖慢队列和网络传输。",
      "构建上下文也是安全边界。进入上下文的文件可能被 COPY 进镜像，也可能影响缓存摘要；敏感凭据应通过 BuildKit secret mount、运行时 secret 或 CI 密钥系统传入。",
      "常见边界包括 Dockerfile 路径和上下文路径混淆、COPY ../file 失败、.dockerignore 误排除依赖文件、大小写路径在不同系统表现不同、Git 上下文只包含提交内容、远程上下文下载失败、空上下文无法 COPY 本地文件。",
      "参考来源：本讲解参考 Docker Build context、Dockerfile reference、Dockerfile best practices、Build cache、Build cache invalidation、Optimize cache usage 和 Build secrets 官方文档。",
    ],
