      "host 网络让容器共享宿主机网络命名空间，减少 NAT 和端口映射层，适合对延迟或端口模型敏感的场景，同时会降低网络隔离。",
      "排查 Docker 网络时先看容器加入了哪个网络、IP 和网关是什么，再看端口是否发布、服务监听地址是否正确、DNS 是否解析、宿主机防火墙和安全组是否放行。",
