    explanation: [
      "数据卷负责保存数据，卷挂载负责把这个卷放到容器内哪个路径。容器应用只认识目标路径，Docker 负责把目标路径背后的存储连接到具体卷对象。",
      "--mount 语法用 type=volume、source、target 明确表达挂载关系，适合脚本和生产部署；-v data:/data 写法更短，适合日常命令和示例。",
      "卷挂载到已有目录时，挂载点会呈现卷里的内容。首次把空卷挂到镜像内已有数据目录时，Docker 会把该目录中的内容复制到卷中；使用 volume-nocopy 可以控制这个行为。",
      "只读卷挂载适合共享配置、证书或初始化数据。应用需要写入日志、数据库文件或缓存时，要确认目标路径具备写权限，并且容器用户 UID/GID 能访问卷内容。",
      "Compose 的 volumes 支持短语法和长语法。长语法可以声明 type、source、target、read_only 和 volume 选项，复杂项目中更利于审查和维护。",
      "排障时看三处：docker inspect 的 Mounts 字段确认 Source 与 Destination，容器内 ls 和 df 查看目标路径状态，docker volume inspect 查看卷位置、驱动和标签。",
      "常见边界包括 source 写错导致新卷被自动创建、target 写到关键目录导致应用文件被遮盖、匿名卷残留、volume-nocopy 行为误判、只读挂载导致写入失败、Compose 相对路径与命名卷语义混淆。",
      "参考来源：本讲解参考 Docker Volumes、Storage volumes、docker container run、docker container inspect、Compose services reference、docker volume create、docker volume inspect 官方文档和 JavaGuide Docker 资料。",
    ],
