      "服务 volumes 支持短语法和长语法。长语法能明确 type、source、target、read_only、volume 子选项，复杂挂载更适合使用长语法审查。",
      "docker compose down 默认移除容器和网络，使用 -v 会同时移除 Compose 创建的命名卷和匿名卷。涉及数据库、消息队列和上传文件时，执行 down -v 前要确认备份和恢复方案。",
      "排障时先用 docker compose config 看最终配置，再用 docker volume ls 和 docker volume inspect 确认真实卷名、驱动和挂载点，最后进入容器检查目标路径内容和权限。",
