      "service 是应用角色，例如 web、api、db；network 负责服务间通信和服务名解析；volume 负责持久化数据。掌握 Compose 要先看这三个对象如何组合。",
      "docker compose up 会按配置创建网络、卷和容器，并启动服务；docker compose down 会停止并移除项目资源。加上 -d 可以后台运行，加上 --build 可以在启动前构建镜像。",
      "Compose 适合本地开发、单机部署、集成测试和小型环境编排。它把启动命令、端口、环境变量、卷挂载和依赖关系写进文件，让团队共享同一套运行拓扑。",
      "Compose 的项目名会影响默认网络、卷和容器名。不同目录或不同 project name 会创建不同资源，排查时要用 docker compose ls、docker compose ps 和 docker network/volume ls 关联起来看。",
      "生产使用 Compose 时要关注镜像版本固定、环境变量来源、密钥管理、健康检查、日志、备份、资源限制和回滚流程。Compose 管应用生命周期，稳定性来自这些工程约束。",
