      ".env 文件常用于 Compose 文件插值，env_file 常用于给容器设置环境变量。environment 字段可以直接写键值，也可以引用当前 shell 环境。",
      "变量插值支持默认值和必填提示，例如 ${TAG:-latest}、${DB_PASSWORD:?missing}。docker compose config 会展示插值后的最终配置，是启动前最重要的检查命令。",
      "环境变量优先级会影响最终容器值。命令行、Compose 文件 environment、env_file、镜像 ENV 等来源都有层级，出现同名变量时要按官方优先级排查。",
      "敏感配置不适合长期放在普通环境变量和 .env 文件里。密码、证书和令牌应优先使用 secrets、外部密钥系统或部署平台的安全注入能力。",
      "常见场景包括区分 dev/staging/prod 配置、设置镜像标签、端口、数据库地址、日志级别和 Feature Flag。每套环境应保留明确的 env 文件和校验流程。",
