    concept: "depends_on 用来声明 Compose 服务之间的启动和停止依赖，并可结合健康检查控制依赖服务达到指定状态后再启动下游服务。",
    explanation: [
      "depends_on 描述服务之间的依赖关系。Compose 会按依赖顺序创建和启动服务，并按相反顺序停止和移除服务。",
      "短语法 depends_on: [db] 表示当前服务启动前先启动 db。这个形式适合简单依赖，主要表达顺序关系。",
      "长语法可以为依赖声明 condition。service_started 表示依赖服务已经启动，service_healthy 表示依赖服务通过 healthcheck，service_completed_successfully 适合迁移任务或一次性初始化任务。",
      "depends_on 和 healthcheck 经常配合使用。数据库、消息队列、缓存这类服务启动后还需要初始化，使用 service_healthy 可以让应用等待依赖进入健康状态。",
      "restart: true 可以让依赖服务被 Compose 显式重启后，下游服务也跟随重启。required 可以描述依赖是否必须存在，适合可选辅助服务。",
      "排障时先用 docker compose config 查看最终依赖图，再用 docker compose ps 看健康状态，用 docker compose logs <service> 查看依赖服务是否真正可用。",
      "常见边界包括依赖服务进程已启动、端口和协议仍在初始化，healthcheck 配置缺失导致下游过早启动，healthcheck 命令依赖镜像内的可执行程序，一次性迁移任务需要 service_completed_successfully，循环依赖会让拓扑难以维护。",
      "参考来源：本讲解参考 Docker Control startup and shutdown order in Compose、Compose services reference、docker compose up、Compose file reference、docker compose、Compose Build Specification 官方文档和 JavaGuide Docker 资料。",
    ],
