    id: "logging-driver",
    zh: "日志驱动",
    en: "Logging Driver",
    area: "observability",
    difficulty: "medium",
    concept: "日志驱动决定容器 stdout/stderr 输出的存储格式、读取方式和外发目标，是容器日志进入本地文件或日志平台的关键插件层。",
    explanation: [
      "日志驱动是 Docker daemon 处理容器日志的机制。容器把 stdout 和 stderr 写给 Docker 后，日志驱动负责把这些日志保存到本地、发送到系统日志或转发到外部日志平台。",
      "Docker daemon 有默认日志驱动，新建容器会继承它。可以在 daemon.json 中设置 log-driver 和 log-opts，也可以在 docker run 或 docker container create 时用 --log-driver、--log-opt 为单个容器覆盖。",
      "默认驱动是 json-file，它把日志按 JSON 行写入 Docker 管理的文件，字段包含 log、stream 和 time。json-file 支持 max-size、max-file、compress、labels、env 等选项。",
      "local 驱动把日志写入 Docker 内部格式，默认带轮转和压缩，每个容器默认保留约 100MB 日志。生产环境常用 local 或显式轮转参数控制磁盘占用。",
      "远程驱动包括 syslog、journald、gelf、fluentd、awslogs、splunk、gcplogs 等。它们适合把容器日志接入统一日志平台，同时需要关注网络、鉴权、缓冲和平台可用性。",
      "日志驱动会影响 docker logs 的本地读取能力。json-file、local、journald 支持本地读取；远程驱动依赖 dual logging 缓存时也可读取，禁用缓存后本地查看能力会受影响。",
      "日志投递模式影响应用稳定性。blocking 模式让日志写入跟随驱动速度，non-blocking 模式使用缓冲减少背压，同时缓冲满时可能丢弃新日志。",
      "常见边界包括修改 daemon.json 后仅影响新建容器、log-opts 数值需要写成字符串、外部日志平台不可用导致阻塞或丢日志、容器输出量过大挤占磁盘、直接读 Docker 内部日志文件干扰 daemon、不同驱动支持的标签和环境变量字段差异。",
      "参考来源：本讲解参考 Docker Configure logging drivers、View container logs、JSON File logging driver、Local file logging driver、Use docker logs with remote logging drivers、docker container run、dockerd 官方文档和 JavaGuide Docker 资料。",
    ],
