      "--pids-limit 控制容器可创建的进程或线程数量，适合限制 fork 风暴和线程暴涨。块 I/O 可通过 --blkio-weight 以及 --device-read-bps、--device-write-bps、--device-read-iops、--device-write-iops 控制。",
      "Docker 通过 cgroup 写入这些限制，docker stats 会展示实际资源使用。排障时把限制配置、实时指标、事件和日志放在同一时间线上观察。",
      "资源限制要按应用画像设置：CPU 密集型服务重点看 CPU 限额和节流，内存型服务重点看 RSS、缓存、swap 和 OOM，I/O 密集型服务重点看块设备读写。",
