      "PIDS 异常上涨时同步查看 docker stats、docker top、应用线程转储和 docker events",
      "安全基线中给暴露面较大的容器设置 PIDs 上限，降低 fork 风暴影响",
      "调低 PIDs 上限后验证启动、健康检查、扩容和高峰流量场景",
