      "镜像加固包括固定可信基础镜像、使用 digest 或受控 tag、定期扫描漏洞、减少包和调试工具、使用多阶段构建、删除构建期产物，并通过 USER 指令设置默认低权限用户。",
      "密钥加固要求敏感值走 BuildKit secret、运行时 secret、外部密钥系统或平台注入。密码、令牌和私钥进入 ARG、ENV、镜像层、history、日志或 inspect 输出后，泄露面会扩大。",
      "加固需要配合审计和可观测性：记录镜像来源、启动参数、capabilities 变更、secret 使用、Docker events、日志、扫描结果和例外审批，方便上线后追溯。",
