    id: "dockerfile-user",
    zh: "USER",
    en: "USER",
    area: "security",
    difficulty: "medium",
    concept:
      "USER 指令在 Dockerfile 中设置当前构建阶段后续指令和容器运行时的默认用户与用户组。",
    explanation: [
      "`USER <user>[:<group>]` 或 `USER <UID>[:<GID>]` 设置默认身份。它会影响当前 stage 后续 `RUN` 指令，也会影响最终容器启动时执行 `ENTRYPOINT` 与 `CMD` 的用户。",
      "USER 是镜像内的默认值，运行时仍可用 `docker run --user` 或 Compose `user` 覆盖。镜像作者用 USER 给出安全默认值，部署侧用运行参数处理环境差异。",
      "推荐在 Dockerfile 前半段用 root 完成包安装、用户创建、目录创建和权限设置，随后切换到应用用户运行构建收尾步骤和应用启动命令。这样镜像启动时天然满足最小权限。",
      "文件权限需要和 USER 同步设计。`COPY --chown=<user>:<group>` 可以在复制时设置属主，`RUN chown` 可处理已存在目录；缓存目录、日志目录、临时目录和应用工作目录都要确认可读写。",
      "使用数字 UID/GID 能降低用户名解析差异；使用用户名可读性更好，但镜像内需要有对应 `/etc/passwd` 与 `/etc/group` 记录。指定 group 时，其他附加组会被忽略，可能影响共享卷权限。",
      "多阶段构建中，每个 stage 都有自己的 USER 状态。上一阶段的 USER 状态不会自动继承到下一阶段，最终镜像要在最后一个 stage 明确设置运行用户。",
      "常见边界包括切换 USER 之后安装软件失败、工作目录属主仍是 root、绑定挂载覆盖了镜像内已赋权目录、低端口监听需要 capability、Windows 容器用户需要先创建、基础镜像升级后用户 ID 变化。",
      "参考来源：本讲解参考 Dockerfile Reference、Dockerfile best practices、docker run、Compose services、Docker Engine security、OWASP Docker Security Cheat Sheet 和 JavaGuide。",
    ],
    typicalProblems: [
      "USER 指令影响 Dockerfile 哪些后续步骤",
      "USER 与 `docker run --user` 的覆盖关系是什么",
      "为什么最终 stage 要显式设置 USER",
      "如何用 `COPY --chown` 配合低权限用户",
      "用户名和数字 UID/GID 如何选择",
      "切换 USER 后包安装失败如何处理",
      "绑定挂载覆盖目录权限如何排查",
      "指定 group 后附加组变化会造成什么影响",
    ],
    commonCommands: [
      "docker build -t app .",
      "docker run --rm app id",
      "docker run --rm --user 1000:1000 app id",
      "docker image inspect app --format '{{.Config.User}}'",
      "docker run --rm app ls -ln /app",
    ],
    practiceAdvice: [
      "在 Dockerfile 中先创建应用用户、目录和权限，再切换到 `USER`",
      "最终 stage 显式写出 `USER`，让镜像默认运行身份清晰可查",
      "复制应用文件时优先使用 `COPY --chown`，减少额外层和权限漂移",
      "上线前运行 `docker run --rm app id` 和关键写路径测试，确认实际用户和目录权限",
      "对需要共享卷的应用，提前约定 UID/GID 或共享组，并在 Compose 中补齐 `user` 或 `group_add`",
    ],
    prerequisites: ["non-root-user", "dockerfile", "image-layer"],
